// Package external implements the /api surface: the public API, authenticated by a Workspace's
// bearer API token.
package external

import (
	"context"
	"time"

	"github.com/getsphericon/sphericon/ent"
	externalapi "github.com/getsphericon/sphericon/gen/external"
	"github.com/getsphericon/sphericon/internal/accounts"
	"github.com/getsphericon/sphericon/internal/api/external/resources"
	"github.com/getsphericon/sphericon/internal/automations"
	"github.com/getsphericon/sphericon/internal/brandkit"
	"github.com/getsphericon/sphericon/internal/broadcasts"
	"github.com/getsphericon/sphericon/internal/capturedmessages"
	"github.com/getsphericon/sphericon/internal/contacts"
	"github.com/getsphericon/sphericon/internal/erasure"
	"github.com/getsphericon/sphericon/internal/eventlog"
	"github.com/getsphericon/sphericon/internal/events"
	"github.com/getsphericon/sphericon/internal/integrations"
	"github.com/getsphericon/sphericon/internal/outbound"
	"github.com/getsphericon/sphericon/internal/reputation"
	"github.com/getsphericon/sphericon/internal/rules"
	"github.com/getsphericon/sphericon/internal/segments"
	"github.com/getsphericon/sphericon/internal/sendingdomains"
	"github.com/getsphericon/sphericon/internal/tags"
	"github.com/getsphericon/sphericon/internal/templates"
	"github.com/getsphericon/sphericon/internal/transactional"
	"github.com/getsphericon/sphericon/internal/webhooks"
)

// mapper turns ent entities into external API resources (generated by goverter).
var mapper = &resources.ConverterImpl{}

// inputs turns request bodies into the modules' inputs (generated by goverter).
var inputs = &resources.InputsImpl{}

type Handlers struct {
	accounts       *accounts.Accounts
	bus            *events.Bus
	eventlog       *eventlog.Module
	outbound       *outbound.Module
	segments       *segments.Module
	webhooks       *webhooks.Module
	integrations   *integrations.Module
	captured       *capturedmessages.Module
	sendingDomains *sendingdomains.Module
	broadcasts     *broadcasts.Module
	reputation     *reputation.Module
	contacts       *contacts.Module
	erasure        *erasure.Module
	tags           *tags.Module
	templates      *templates.Module
	transactional  *transactional.Module
	brandKit       *brandkit.Module
	automations    *automations.Module
	rules          *rules.Module
	bootstrapToken string
	audit          AuditLog
	export         ExportStreams
}

// AuditLog is the read seam of the Enterprise Audit log (ADR 0022), implemented by
// ee/audit. Core knows only this interface: without a license Licensed is false and
// the read answers 402.
type AuditLog interface {
	Licensed() bool
	// Entries returns up to limit entries, newest first, preceding the cursor entry
	// id (0 = from the newest), and the next page's cursor (0 = last page).
	Entries(ctx context.Context, s *ent.Scoped, f events.AuditFilter, cursor int64, limit int) ([]*ent.AuditEntry, int64, error)
}

// ExportStreams is the license seam of the Enterprise Export streams (ADR 0045),
// implemented by ee/export. Core serves the streams itself (internal/exportstream) and
// asks only whether the `export` feature is licensed: without it every stream answers 404.
type ExportStreams interface {
	Licensed() bool
}

// Deps is everything the /api handlers are built from. The domain modules are
// the shared singletons the composition root registers once, so /api and /site
// cannot diverge on how a module is constructed.
type Deps struct {
	Accounts     *accounts.Accounts
	Bus          *events.Bus
	Webhooks     *webhooks.Module
	Integrations *integrations.Module
	// CapturedMessages is the store of what the Workspace's Test inbox kept.
	CapturedMessages *capturedmessages.Module
	SendingDomains   *sendingdomains.Module
	Outbound         *outbound.Module
	Segments         *segments.Module
	EventLog         *eventlog.Module
	Contacts         *contacts.Module
	Erasure          *erasure.Module
	Tags             *tags.Module
	Templates        *templates.Module
	Transactional    *transactional.Module
	BrandKit         *brandkit.Module
	Automations      *automations.Module
	Rules            *rules.Module
	Broadcasts       *broadcasts.Module
	Reputation       *reputation.Module
	BootstrapToken   string
	Audit            AuditLog
	Export           ExportStreams
	// Clock is the time a Connection's Two-factor requirement is checked against (nil means
	// time.Now); the security handler reads it.
	Clock func() time.Time
}

func NewHandlers(d Deps) *Handlers {
	return &Handlers{
		accounts: d.Accounts, bus: d.Bus, webhooks: d.Webhooks, integrations: d.Integrations, captured: d.CapturedMessages, sendingDomains: d.SendingDomains, outbound: d.Outbound, segments: d.Segments,
		eventlog: d.EventLog, contacts: d.Contacts, erasure: d.Erasure, tags: d.Tags, templates: d.Templates, transactional: d.Transactional, brandKit: d.BrandKit, automations: d.Automations, rules: d.Rules,
		broadcasts: d.Broadcasts, reputation: d.Reputation, bootstrapToken: d.BootstrapToken,
		audit: d.Audit, export: d.Export,
	}
}

var _ externalapi.Handler = (*Handlers)(nil)
